// one-time setup: device key (per boot), config, pin the platform key, register
const dev = "real-powerplant-blatnica";
flow.set("device_id", dev);
flow.set("platform", "https://gridzilla.victronlab.sk");
flow.set("path", ["region:at", "sub:wien-sued", "feeder:liesing-3", "tf:atzgersdorf-1"]);
const dir = os.homedir() + "/.node-red/gridzilla"; fs.mkdirSync(dir, { recursive: true }); flow.set("dir", dir);
const kp = dir + "/device.key.pem";
if (!fs.existsSync(kp)) { const { privateKey } = crypto.generateKeyPairSync("ed25519"); fs.writeFileSync(kp, privateKey.export({ type: "pkcs8", format: "pem" }), { mode: 0o600 }); }
const priv = crypto.createPrivateKey(fs.readFileSync(kp));
flow.set("device_priv", priv.export({ type: "pkcs8", format: "pem" }).toString());
flow.set("device_pub", crypto.createPublicKey(priv).export({ type: "spki", format: "pem" }).toString());
const pp = dir + "/platform.pub.pem"; if (fs.existsSync(pp)) flow.set("platform_pub", fs.readFileSync(pp, "utf8"));
const st = dir + "/state.json"; if (fs.existsSync(st)) { const j = JSON.parse(fs.readFileSync(st, "utf8")); flow.set("last_seq", j.last_seq || 0); flow.set("last_hb_seq", j.last_hb_seq || 0); }
if (!flow.get("owner")) flow.set("owner", { min_soc: 20, max_charge_kw: 5, max_discharge_kw: 5, feedin_max_kw: 10, opt_out: false });
flow.set("ess_defaults", {"/Settings/CGwacs/AcPowerSetPoint": 90, "/Settings/CGwacs/MaxFeedInPower": 10000, "/Settings/CGwacs/MaxChargePower": -1, "/Settings/CGwacs/MaxDischargePower": 5000});
msg.url = flow.get("platform") + "/api/pubkey"; msg.method = "GET";
return msg;

if (!flow.get("platform_pub")) { flow.set("platform_pub", msg.payload); fs.writeFileSync(flow.get("dir") + "/platform.pub.pem", msg.payload); node.warn("platform key pinned (TOFU) and stored"); }
msg.url = flow.get("platform") + "/api/register"; msg.method = "POST";
msg.headers = { "Content-Type": "application/json" };
msg.payload = { device: flow.get("device_id"), pubkey_pem: flow.get("device_pub") };
return msg;

const r = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
if (r && r.path) { flow.set("path", r.path); node.status({ fill: "green", shape: "dot", text: "registered " + r.path.join(">") }); }
else node.status({ fill: "red", shape: "ring", text: "registration failed" });
return null;

// Node-RED function node: VERIFY + SCOPE + FRESHNESS
// Wire: [mqtt in: gridzilla/sig/# and gridzilla/hb] -> this -> [merge.js]
// Setup tab: Modules -> add "crypto" as `crypto` (Node-RED >= 1.3, functionExternalModules: true in settings).
// On Venus OS Large: /data/home/nodered/.node-red/settings-user.js  ->  functionExternalModules: true
//
// Context expected (set once at registration / in a startup inject):
//   flow.platform_pub   : platform public key PEM, fetched from GET /api/pubkey and pinned (trust on first use)
//   flow.device_id      : e.g. "real-powerplant-blatnica"
//   flow.path           : ["region:at","sub:wien-sued","feeder:liesing-3","tf:atzgersdorf-1"]
//   flow.last_seq       : last accepted signal seq (persisted context store recommended)
//
// Outputs: 1 = verified signal (msg.signal), 2 = ack to publish (msg.topic/msg.payload), 3 = heartbeat ok (msg.hb = true)

const env = msg.payload;                              // {v, kid, payload, sig}
const pubPem = flow.get("platform_pub");
if (!pubPem) { node.error("no pinned platform key"); return null; }

const ok = env && env.v === 1 && typeof env.payload === "string" && typeof env.sig === "string" &&
  crypto.verify(null, Buffer.from(env.payload, "utf8"), crypto.createPublicKey(pubPem), Buffer.from(env.sig, "base64"));

const ack = (seq, status, reason) => ({
  topic: `gridzilla/ack/${flow.get("device_id")}`,
  ackdoc: { v: 1, device: flow.get("device_id"), path: flow.get("path"), seq, status, reason,
            applied: flow.get("effective") || {}, soc: flow.get("soc") || 0, grid_kw: flow.get("grid_kw") || 0,
            ts: new Date().toISOString().replace(/\.\d{3}Z$/, "Z") }
});

if (!ok) { node.warn("bad_sig"); return [null, ack(null, "refused", "bad_sig"), null]; }

const doc = JSON.parse(env.payload);

if (msg.topic === "gridzilla/hb") {
  const hbAge = (Date.now() - Date.parse(doc.ts)) / 1000;
  if (!(doc.seq > (flow.get("last_hb_seq") || 0)) || hbAge > 90 || hbAge < -30) return null;   // replayed or stale heartbeat: ignore
  flow.set("last_hb_seq", doc.seq); flow.set("last_hb", Date.now());
  return [null, null, { hb: true }];
}

if (!(flow.get("path") || []).includes(doc.segment)) return null;        // not for me
if (doc.cohort && (parseInt(crypto.createHash("sha256").update(flow.get("device_id")).digest("hex").slice(0, 8), 16) % doc.cohort[1]) !== doc.cohort[0]) return null; // not my cohort

const lastSeq = flow.get("last_seq") || 0;
if (doc.seq <= lastSeq) { node.warn(`stale_seq ${doc.seq} <= ${lastSeq}`); return [null, ack(doc.seq, "refused", "stale_seq"), null]; }

const age = (Date.now() - Date.parse(doc.issued_at)) / 1000;
if (age > 120 || age < -30 || Date.parse(doc.valid_to) < Date.now()) return [null, ack(doc.seq, "refused", "expired"), null];

flow.set("last_seq", doc.seq); try { fs.writeFileSync(flow.get("dir") + "/state.json", JSON.stringify({ last_seq: doc.seq, last_hb_seq: flow.get("last_hb_seq") || 0 })); } catch (e) {}
msg.signal = doc;
return [msg, null, null];

// Node-RED function node: MERGE WITH OWNER LIMITS + APPLY PLAN
// Wire: [verify.js out 1] -> this -> out 1: Victron writes, out 2: ack, out 3: schedule revert
//
// Owner limits come from the ESS settings on the GX (read once with victron nodes or set in flow context):
//   flow.owner = { min_soc: 20, max_charge_kw: 5, max_discharge_kw: 5, feedin_max_kw: 10, opt_out: false }
// Saved ESS values for revert (read before the first write):
//   flow.saved = { AcPowerSetPoint, MaxChargePower, MaxDischargePower, MaxFeedInPower }
//
// Output 1 is a list of {setting, value} pairs for the Victron "ESS control" / settings nodes:
//   /Settings/CGwacs/MaxFeedInPower, /Settings/CGwacs/MaxChargePower, /Settings/CGwacs/MaxDischargePower, /Settings/CGwacs/AcPowerSetPoint

const sig = msg.signal;
const o = flow.get("owner");
const soc = flow.get("soc") || 0;
const dev = flow.get("device_id");
const ts = () => new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
const ack = (status, reason, applied) => ({ topic: `gridzilla/ack/${dev}`,
  ackdoc: { v: 1, device: dev, path: flow.get("path"), seq: sig.seq, status, reason, applied: applied || {},
            soc, grid_kw: flow.get("grid_kw") || 0, ts: ts() } });

if (sig.mode === "RELEASE") {
  flow.set("effective", null);
  return [{ payload: "revert" }, ack("applied", null, {}), null];
}
if (o.opt_out) return [null, ack("refused", "opt_out"), null];

const eff = { mode: sig.mode, import_max_kw: null, export_max_kw: null, export_min_kw: null,
              charge_max_kw: null, discharge_max_kw: null, target_soc: null };
let status = "applied", reason = null;

if (sig.import_max_kw != null) eff.import_max_kw = sig.import_max_kw;
if (sig.export_max_kw != null) eff.export_max_kw = Math.min(sig.export_max_kw, o.feedin_max_kw);  // never above the owner's feed-in limit
if (sig.mode === "STRETCH") eff.export_max_kw = 0;                            // street is dark: lock export, no backfeed
if (sig.charge_max_kw != null) eff.charge_max_kw = Math.min(sig.charge_max_kw, o.max_charge_kw);
if (sig.discharge_max_kw != null) eff.discharge_max_kw = Math.min(sig.discharge_max_kw, o.max_discharge_kw);
if (sig.target_soc != null) eff.target_soc = sig.target_soc;                 // only ever raises SoC
if (sig.export_min_kw != null) {
  const cap = Math.min(o.feedin_max_kw, o.max_discharge_kw);
  if (soc <= o.min_soc)            { eff.export_min_kw = 0;   status = "partial"; reason = "min_soc"; }
  else if (sig.export_min_kw > cap) { eff.export_min_kw = cap; status = "partial"; reason = "owner_limit"; }
  else                              { eff.export_min_kw = sig.export_min_kw; }
}
flow.set("effective", eff);

// Translate the envelope into ESS writes. Everything is a limit; the grid setpoint is the one "push".
const W = 1000;
const writes = [];
if (eff.export_max_kw != null) writes.push({ setting: "/Settings/CGwacs/MaxFeedInPower", value: eff.export_max_kw * W });
if (eff.charge_max_kw != null) writes.push({ setting: "/Settings/CGwacs/MaxChargePower", value: eff.charge_max_kw * W });
if (eff.discharge_max_kw != null) writes.push({ setting: "/Settings/CGwacs/MaxDischargePower", value: eff.discharge_max_kw * W });
if (eff.export_min_kw != null && eff.export_min_kw > 0)
  writes.push({ setting: "/Settings/CGwacs/AcPowerSetPoint", value: -eff.export_min_kw * W });   // forced feed-in
else if (eff.import_max_kw != null)
  writes.push({ setting: "/Settings/CGwacs/AcPowerSetPoint", value: 0, cap_import_w: eff.import_max_kw * W }); // keep grid <= cap; a small loop node enforces the cap
if (eff.target_soc != null)                                               // PREPARE: pull charge power from the grid until target SoC (watchdog ends it)
  writes.push({ setting: "/Settings/CGwacs/AcPowerSetPoint", value: Math.round((eff.charge_max_kw ?? o.max_charge_kw) * W) });

const ramp = sig.ramp_s[0] + Math.random() * (sig.ramp_s[1] - sig.ramp_s[0]);
const live = ["ABSORB", "SUPPORT"].includes(sig.mode);     // needs heartbeat; PREPARE/STRETCH/RECOVER run offline to valid_to
const maxEnd = Date.parse(sig.valid_from) + (sig.mode === "STRETCH" ? 4320 : 1440) * 60 * 1000;   // protocol: 24 h max per signal, renewable; STRETCH 3 days
const endAt = Math.min(Date.parse(sig.valid_to), maxEnd);                                        // device enforces it, not only the platform
const plan = { seq: sig.seq, writes, start_at: Math.min(Math.max(Date.now(), Date.parse(sig.valid_from)) + ramp * 1000, endAt - 1000),
               end_at: endAt, watchdog: live, hb_timeout_s: 120 };   // the ramp never pushes the writes past the window

return [{ payload: plan }, ack(status, reason, eff), { payload: { end_at: plan.end_at, watchdog: live } }];

// sign an ack document with the device key -> envelope
const payload = JSON.stringify(msg.ackdoc);
const sig = crypto.sign(null, Buffer.from(payload, "utf8"), crypto.createPrivateKey(flow.get("device_priv"))).toString("base64");
msg.payload = JSON.stringify({ v: 1, kid: "dev", payload, sig });
return msg;

// msg.payload = plan {writes:[{setting,value}], start_at, end_at, watchdog} or "revert"
// outputs 0-3: ESS settings; 4: EV /SetCurrent (A); 5: EV /StartStop (0/1); 6: EV /Mode (0 manual)
const W = { "/Settings/CGwacs/MaxFeedInPower": 0, "/Settings/CGwacs/MaxChargePower": 1, "/Settings/CGwacs/MaxDischargePower": 2, "/Settings/CGwacs/AcPowerSetPoint": 3 };
const out = [null, null, null, null, null, null, null];
if (msg.payload === "revert") {
  const saved = Object.assign({}, flow.get("ess_defaults") || {}, flow.get("saved") || {});   // live snapshot wins, owner defaults fill the gaps
  for (const [s, i] of Object.entries(W)) if (saved[s] != null) out[i] = { payload: saved[s] };
  const ev = flow.get("ev_saved");
  if (ev) { out[6] = { payload: ev.mode }; out[4] = { payload: ev.setcurrent }; out[5] = { payload: ev.startstop }; flow.set("ev_saved", null); }
  flow.set("effective", null); flow.set("plan", null); flow.set("ev_limit", null);
  node.status({ fill: "grey", shape: "ring", text: "owner mode" });
  return out;
}
const plan = msg.payload;
if (!flow.get("saved")) flow.set("saved", { ...(flow.get("current") || {}) });   // snapshot once, restore on revert
flow.set("plan", plan);
const delay = Math.max(0, plan.start_at - Date.now());
setTimeout(() => {
  const cur = flow.get("plan");
  if (!cur || cur.seq !== plan.seq || Date.now() >= plan.end_at) return;   // reverted or replaced while waiting: never write a stale plan
  const o = [null, null, null, null, null, null, null];
  for (const w of plan.writes) if (W[w.setting] != null) o[W[w.setting]] = { payload: w.value };
  // EV charger: first lever. Remember mode/current/startstop once, switch to manual, apply a current ceiling.
  const eff = flow.get("effective") || {}, evp = flow.get("ev") || {};
  if (flow.get("ev_present")) {
    if (!flow.get("ev_saved")) flow.set("ev_saved", { mode: evp.mode ?? 0, setcurrent: evp.setcurrent ?? 16, startstop: evp.startstop ?? 1 });
    o[6] = { payload: 0 };                                                   // manual: our current setting is honoured
    if (eff.mode === "STRETCH") { o[5] = { payload: 0 }; flow.set("ev_limit", 0); }
    else if (eff.import_max_kw != null) flow.set("ev_limit", "cap");        // live loop below keeps grid <= cap by trimming the car first
    else if (eff.export_max_kw != null) flow.set("ev_limit", "soak");       // live loop raises the car to absorb surplus
  }
  node.send(o);
  node.status({ fill: "yellow", shape: "dot", text: (flow.get("effective") || {}).mode + " until " + new Date(plan.end_at).toISOString().slice(11, 16) });
}, delay);
return null;

// every 5 s: (a) EV current loop while a cap is active, (b) window end or heartbeat loss -> revert
const plan = flow.get("plan"); if (!plan) return null;
const eff = flow.get("effective") || {};
const lim = flow.get("ev_limit"), ev = flow.get("ev") || {};
if (lim === "cap" || lim === "soak") {
  const perAmp = (ev.power > 100 && ev.setcurrent > 0) ? ev.power / ev.setcurrent : 230 * (ev.phases || 1);   // W per ampere, measured when charging
  const gridW = (flow.get("grid_kw") || 0) * 1000, evW = ev.power || 0;
  let targetW = lim === "cap" ? Math.max(0, eff.import_max_kw * 1000 - (gridW - evW)) : Math.max(0, evW + (-(eff.export_max_kw * 1000) - gridW) * -1);
  let amps = Math.floor(targetW / perAmp);
  amps = Math.min(amps, ev.maxcurrent || 16);
  if (amps < 6) amps = 0;                                                     // below 6 A the car stops anyway: pause instead of a dead band
  if (amps !== (ev.last_amps ?? -1)) { ev.last_amps = amps; flow.set("ev", ev);
    node.send([null, null, { payload: amps > 0 ? amps : 6 }, { payload: amps > 0 ? 1 : 0 }]); }
}
const hbAge = (Date.now() - (flow.get("last_hb") || 0)) / 1000;
let reason = null;
if (Date.now() >= plan.end_at) reason = "window_end";
else if (eff.target_soc != null && (flow.get("soc") || 0) >= eff.target_soc) reason = "window_end";   // PREPARE target reached
else if (plan.watchdog && hbAge > plan.hb_timeout_s) reason = "heartbeat_lost";
if (!reason) return null;
const ts = new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
const ack = { topic: `gridzilla/ack/${flow.get("device_id")}`, ackdoc: { v: 1, device: flow.get("device_id"), path: flow.get("path"), seq: null,
  status: "reverted", reason, applied: {}, soc: flow.get("soc") || 0, grid_kw: flow.get("grid_kw") || 0, ts } };
node.warn("REVERT: " + reason);
return [{ payload: "revert" }, ack, null, null];

const ev = flow.get("ev") || {}; const k = { "/Ac/Power": "power", "/Mode": "mode", "/Status": "status", "/SetCurrent": "setcurrent", "/MaxCurrent": "maxcurrent", "/StartStop": "startstop", "/Ac/L2/Power": "l2" }[msg.path || msg.topic];
if (k) { ev[k] = msg.payload; if (k === "l2") ev.phases = msg.payload > 50 ? 3 : 1; flow.set("ev", ev); flow.set("ev_present", true); }
return null;

// sum of the three grid phases, W -> kW, + import / - export
const g = flow.get("gridw") || {}; g[msg.topic || msg.path || "L"] = msg.payload; flow.set("gridw", g);
flow.set("grid_kw", Object.values(g).reduce((s, v) => s + (v || 0), 0) / 1000);
return null;

const eff = flow.get("effective");
msg.topic = `gridzilla/state/${flow.get("device_id")}`;
const ev = flow.get("ev") || {};
msg.payload = JSON.stringify({ soc: flow.get("soc") || 0, grid_kw: flow.get("grid_kw") || 0, mode: eff ? eff.mode : "owner", ev_kw: (ev.power || 0) / 1000, ev_status: ev.status ?? null,
  ts: new Date().toISOString().replace(/\.\d{3}Z$/, "Z") });
return msg;
